import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

public class DatasetUtilities_iterateRangeBounds_TriageGen2Test {

    @Mock
    private XYDataset mockXYDataset;

    @Mock
    private IntervalXYDataset mockIntervalXYDataset;

    @Mock
    private OHLCDataset mockOHLCDataset;

    public DatasetUtilities_iterateRangeBounds_TriageGen2Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testStandardXYDataset_NormalValues() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(10.0);
        when(mockXYDataset.getYValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testStandardXYDataset_WithNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(mockXYDataset.getYValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testStandardXYDataset_Empty() {
        when(mockXYDataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertNull(result);
    }

    @Test
    public void testIntervalXYDataset_IncludeInterval_Normal() {
        // Note: We use the mock casted to IntervalXYDataset
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        // value = 15, start = 5, end = 25
        when(mockIntervalXYDataset.getYValue(0, 0)).thenReturn(15.0);
        when(mockIntervalXYDataset.getStartYValue(0, 0)).thenReturn(5.0);
        when(mockIntervalXYDataset.getEndYValue(0, 0)).thenReturn(25.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalXYDataset, true);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(25.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIntervalXYDataset_IncludeInterval_WithNaN() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        when(mockIntervalXYDataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalXYDataset.getStartYValue(0, 0)).thenReturn(10.0);
        when(mockIntervalXYDataset.getEndYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalXYDataset, true);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testOHLCDataset_IncludeInterval_Normal() {
        when(mockOHLCDataset.getSeriesCount()).thenReturn(1);
        when(mockOHLCDataset.getItemCount(0)).thenReturn(1);
        when(mockOHLCDataset.getLowValue(0, 0)).thenReturn(100.0);
        when(mockOHLCDataset.getHighValue(0, 0)).thenReturn(200.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockOHLCDataset, true);

        assertEquals(100.0, result.getLower(), 1e-9);
        assertEquals(200.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testOHLCDataset_IncludeInterval_WithNaN() {
        when(mockOHLCDataset.getSeriesCount()).thenReturn(1);
        when(mockOHLCDataset.getItemCount(0)).thenReturn(1);
        when(mockOHLCDataset.getLowValue(0, 0)).thenReturn(Double.NaN);
        when(mockOHLCDataset.getHighValue(0, 0)).thenReturn(50.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockOHLCDataset, true);

        assertEquals(50.0, result.getLower(), 1e-9);
        assertEquals(50.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIncludeInterval_ButNotIntervalDatasetType() {
        // If includeInterval is true but dataset is a plain XYDataset, it should fall into the 'else' block
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, true);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testAllNaNValues_ReturnsNull() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertNull(result);
    }
}
